package com.pianoscorefollower.app.follower

import com.pianoscorefollower.app.audio.LogSpectralEnergy
import org.junit.Assert.*
import org.junit.Assume.assumeNotNull
import org.junit.Test
import java.io.File
import java.nio.ByteBuffer
import java.nio.ByteOrder

/** External fixtures are generated by upstream itself, not by this port. */
class MatchmakerParityTest {
    private fun floats(path: File): FloatArray {
        val b = ByteBuffer.wrap(path.readBytes()).order(ByteOrder.LITTLE_ENDIAN)
        return FloatArray(b.remaining()/4) { b.float }
    }
    @Test fun upstreamGoldenPath() {
        val path = System.getenv("PIANO_MATCHMAKER_GOLDEN")
        assumeNotNull(path)
        val dir = File(path!!)
        val reference = floats(File(dir,"reference-features.f32")).toList().chunked(84).map { it.toFloatArray() }.toTypedArray()
        val input = floats(File(dir,"input-features.f32"))
        val expected = ByteBuffer.wrap(File(dir,"positions.i32").readBytes()).order(ByteOrder.LITTLE_ENDIAN)
        val tracker = ArztOnlineTimeWarping(reference)
        // The fixture supplies only active frames, exactly as used by upstream.
        for (i in 0 until input.size/84) assertEquals("frame $i", expected.int, tracker.accept(input.copyOfRange(i*84,(i+1)*84)))
    }
    @Test fun silenceProducesNoFabricatedFeatures() {
        val processor = LogSpectralEnergy()
        var frames = 0
        processor.accept(FloatArray(44100)) { feature, _, _ -> frames++; assertTrue(feature.all { it == 0f }) }
        assertEquals(42,frames)
    }
    @Test fun matchingLongSequenceCannotTeleport() {
        val reference = Array(2000) { i -> FloatArray(84).also { it[(i/3)%84]=1f } }
        val tracker = ArztOnlineTimeWarping(reference)
        for (i in 0 until 1000) {
            val before=tracker.frame
            val after=tracker.accept(reference[i])
            assertTrue(after>=before && after<=before+3)
        }
        assertTrue("should follow rather than merely remain stationary",tracker.frame>900)
    }
}
